export const CATEGORIES: Category[] = ["Data reliability", "Data systems", "Analytics & BI", "Running a data function"];
export const AUDIENCES: Audience[] = ["Small businesses", "Startups & scale-ups", "Large companies"];

/** The piece the index leads with: the guide most likely to turn an owner or
 *  founder into a conversation (simulated visitor panel, 21 Oct 2026). */
export const FEATURED_SLUG = "first-reporting-stack";

/** Default index order: buyer-decision guides that lead to a service first,
 *  interleaved by segment; practitioner how-tos last. Unlisted slugs keep
 *  their registry order at the end. */
const ORDER = [
  "first-reporting-stack", "why-dashboards-disagree", "saas-metrics-from-stripe", "connect-quickbooks-xero-to-power-bi",
  "gdpr-deletion-requests-data-warehouse", "when-to-hire-a-data-team", "investor-ready-arr", "shopify-payouts-xero-ga4-revenue",
  "warehouse-migration-parity", "automate-monthly-reporting", "before-you-build-a-data-warehouse", "power-bi-licensing-small-business",
  "crm-closed-won-vs-stripe", "multi-entity-consolidation", "incremental-models-at-scale", "power-bi-warehouse-or-both",
  "one-customer-view", "fabric-capacity-throttling", "power-bi-refresh-failed", "power-bi-slow", "excel-cleaning-automation",
  "reduce-fivetran-costs", "warehouse-platform-costs", "change-data-capture", "is-our-data-reliable", "customer-history-scd2",
  "dbt-fusion-upgrade", "speed-up-dbt-runs",
];
const rank = (slug: string) => { const i = ORDER.indexOf(slug); return i < 0 ? ORDER.length : i; };
articles.sort((a, b) => rank(a.slug) - rank(b.slug));

export function getArticle(slug: string): Article | undefined {
  return articles.find((a) => a.slug === slug);
}

const SITE = "https://thebredge.com";

/** Page metadata for an insight, from the registry (title <= 60, description <= 155). */
export function insightMetadata(slug: string): Metadata {
  const a = getArticle(slug);
  if (!a) return {};
  return pageMetadata({ title: a.seoTitle, description: a.seoDescription, path: `/insights/${slug}` });
}

/** FAQPage JSON-LD from [question, answer] pairs. */
export function faqJsonLd(faq: Article["faq"]) {
  return {
    "@context": "https://schema.org", "@type": "FAQPage",
    mainEntity: faq.map(([q, ans]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: ans } })),
  };
}

/** Article, FAQPage and BreadcrumbList JSON-LD for one insight. */
export function insightJsonLd(a: Article) {
  const url = `${SITE}/insights/${a.slug}`;
  const org = { "@type": "Organization", name: "The Bredge", url: SITE };
  return [
    {
      "@context": "https://schema.org", "@type": "Article",
      headline: a.title, description: a.seoDescription, abstract: a.answer,
      // AUTHOR: replace with a named Person ({ "@type": "Person", name, jobTitle, url, sameAs })
      // once a verified author and author page exist. Until then the organisation is the author.
      author: org,
      publisher: org,
      datePublished: a.date, dateModified: a.updated || a.date,
      mainEntityOfPage: url, url, inLanguage: "en-GB",
      articleSection: a.category, keywords: a.keyword,
      about: a.keyword,
      ...(a.mentions?.length ? { mentions: a.mentions.map((name) => ({ "@type": "Thing", name })) } : {}),
      ...(a.sources?.length ? { citation: a.sources.map(([name, url]) => ({ "@type": "CreativeWork", name, url })) } : {}),
      image: `${SITE}/og.png`,
    },
    faqJsonLd(a.faq),
    {
      "@context": "https://schema.org", "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Home", item: `${SITE}/` },
        { "@type": "ListItem", position: 2, name: "Insights", item: `${SITE}/insights` },
        { "@type": "ListItem", position: 3, name: a.title, item: url },
      ],
    },
  ];
}
